CREATE OR REPLACE FUNCTION public.glaze_in_stores(p_world uuid, p_uid uuid, p_x double precision, p_y double precision)
 RETURNS TABLE(id bigint, x integer, y integer, cx double precision, cy double precision)
 LANGUAGE sql
